package com.nextrade.common.util; import java.util.regex.Pattern; public final class IdempotencyKeys {private static final Pattern P=Pattern.compile("[A-Za-z0-9._:-]{8,128}");private IdempotencyKeys(){} public static String validate(String key){String k=Validation.notBlank(key,"Idempotency-Key");if(!P.matcher(k).matches())throw new IllegalArgumentException("Invalid idempotency key");return k;}}